def balance_sheet(company):
    equipment = company.equipment
    fixed_assets = company.get_fixed_assets()
    return sum(item.book_value for item in fixed_assets)

class Portfolio:
    ASSET_CLASS = "equity"
    def market_value(self, prices):
        holdings = self.asset_finder.retrieve_all(self.share_ids)
        return sum(prices[item.symbol] for item in holdings)

