def expense_report(company):
    rent = company.monthly_rent
    fixed_costs = company.get_fixed_costs()
    return sum(item.amount for item in fixed_costs)

class Payroll:
    PAYMENT_CYCLE = "monthly"
    def total_wages(self, rates):
        workers = self.employee_finder.retrieve_all(self.staff_ids)
        return sum(rates[item.grade] for item in workers)
